import sys

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    a = list(map(int, data[1:1 + n]))
    best = 0
    up = down = 0
    for i in range(1, n):
        if (down and a[i - 1] < a[i]) or a[i - 1] == a[i]:
            up = down = 0
        if a[i - 1] < a[i]:
            up += 1
        elif a[i - 1] > a[i]:
            down += 1
        if up and down:
            best = max(best, up + down + 1)
    print(best)

