best = 0
for l in range(n):
    for r in range(l + 2, n):
        seg = a[l:r + 1]
        k = 0
        while k + 1 < len(seg) and seg[k] < seg[k + 1]:
            k += 1
        if k == 0 or k == len(seg) - 1:
            continue
        ok = True
        for j in range(k, len(seg) - 1):
            if not seg[j] > seg[j + 1]:
                ok = False
                break
        if ok:
            best = max(best, len(seg))
print(best)

